from lib import *
S = SS('u155')
R = J('u155'); F = R['flags']; D = R['dbg']; d0, dl, d2 = D['0'], D['"line-tables-only"'], D['2']
steps = [
    step("cargo build -v 能看到每个 profile 真正传给 rustc 的 -C 参数。dev:debuginfo=2、incremental=<…>/target/debug/incremental,没有 opt-level 参数(即默认的 0);release:opt-level=3、strip=debuginfo,没有 debuginfo、没有 incremental;cargo test 用的 test profile 与 dev 一致:debuginfo=2 与增量。release 默认就带 strip=debuginfo。", t=tl(S(1)), done=lidx(S(1), 'dev ', 'release ', 'test(cargo test)'), kv=KV([['dev', 'debuginfo=2 + 增量,opt-level 0'], ['release', 'opt-level=3 + strip=debuginfo'], ['test', '同 dev']], ['release'])),
    step("依赖单独调优:[profile.dev.package.\"*\"] opt-level = 3 之后,itoa(依赖)的参数里多了 opt-level=3,自己的 u155 仍然是 dev 的默认(没有 opt-level、有 incremental)。常用做法:自己的代码保持快速编译,依赖(尤其是 serde、image 这类重计算库)在 dev 里也用优化。", t=tl(S(2)), done=lidx(S(2), 'itoa(依赖)', 'u155(自己)'), kv=KV([['依赖 itoa', 'opt-level=3'], ['自己的代码', '仍是 dev 默认']], ['依赖 itoa'])),
    step("自定义 profile:[profile.fastdev] inherits = \"dev\",再覆盖 opt-level = 2、debug = false,cargo build --profile fastdev 生效:参数里 opt-level=2,增量目录是 target/fastdev/incremental,产物在独立的 target/fastdev/ 目录,不会污染 target/debug。--profile nonexistent 报 error: profile `nonexistent` is not defined。", t=tl(S(3)), done=lidx(S(3), 'fastdev →', '产物目录'), mark=lidx(S(3), 'nonexistent'), kv=KV([['inherits', '继承后覆盖个别项'], ['产物目录', 'target/fastdev']], ['产物目录'])),
    step(f"debug 级别对二进制本身几乎没有影响:release 加 strip = false,debug = 0 的二进制 {d0[0]:,} 字节,line-tables-only 与 2 都是 {dl[0]:,} 字节(差 3 KB,没有差别 —— macOS 上调试信息默认留在目标文件里,不打进二进制)。但整个 target/release 目录变大:{d0[1]:,} → {dl[1]:,} → {d2[1]:,} 字节。想要调试信息进二进制要换 split-debuginfo 等设置,本文没有验证。", t=tl(S(4)), done=lidx(S(4), 'debug = 0', 'line-tables-only', 'debug = 2'), b=bars([['debug=0 目录', d0[1], f'{d0[1]:,}'], ['line-tables-only 目录', dl[1], f'{dl[1]:,}'], ['debug=2 目录', d2[1], f'{d2[1]:,}']], d2[1], done=[0, 1, 2]), kv=KV([['二进制', f'{d0[0]:,} → {d2[0]:,} 字节(几乎不变)'], ['target/release 目录', f'{d0[1]:,} → {d2[1]:,} 字节']], ['target/release 目录'])),
    step("build.rs 的编译参数与目标代码是分开的:release 构建里,目标代码 u155b 的参数有 opt-level=3,而 build_script_build 的 -C 参数里没有 opt-level(默认 0)、debug-assertions=off,只是为了快速编译构建脚本。可以用 [profile.release.build-override] 单独调整它们(这里没有尝试)。", t=tl(S(5)), done=lidx(S(5), 'build_script_build', '目标代码 u155b'), kv=KV([['目标代码', 'opt-level=3'], ['build.rs', '没有 opt-level(默认 0)']], ['build.rs'])),
]
A = mkart('u155', 155, 'Rust,Cargo,profile,构建配置,真实验证,动画演示',
    f'用 cargo build -v 验证 Cargo profile 的真实参数:dev 与 release 的 -C 参数、[profile.dev.package."*"] 让依赖单独 opt-level=3、自定义 fastdev profile(inherits)的产物目录、debug 级别不改变 macOS 二进制({d0[0]:,} → {d2[0]:,} 字节)但 target/release 目录从 {d0[1]:,} 涨到 {d2[1]:,} 字节、build.rs 不带 opt-level。',
    '上一篇比较了 debug 与 release 的速度,这一篇换一个角度:profile 到底在配置什么?它们真实传给 rustc 的参数是什么?怎样给依赖单独调优、自定义 profile、调整调试信息?全部用 cargo -v 的输出和真实文件大小回答。',
    [('-v', '用 cargo build -v 直接看 profile 展开成 rustc 的 -C 参数'), ('inherits', '自定义 profile 继承 dev 并覆盖个别配置'), (f'{d0[1] // 1000} → {d2[1] // 1000} KB', 'debug = 0 与 2 时整个 target/release 目录的大小(二进制本身几乎不变)')],
    [('profile 展开成什么参数', '<p>dev 与 release 的耗时对比见<a href="rust-debug-vs-release.html">Debug 与 Release 构建差异</a>;LTO 与体积见<a href="rust-lto-binary-size.html">LTO 与二进制体积</a>。</p>'), ('给依赖单独调优', None), ('自定义 profile', None), ('调试信息的级别', '<p>macOS 的调试信息保存方式与 Linux 不同;这里的「二进制几乎不变」是 macOS 上的结果。</p>'), ('build-override', '<p>build.rs 的更多行为见<a href="rust-build-rs.html">Build Script build.rs</a>。</p>')],
    steps, [ENV_U + '。macOS(split-debuginfo 默认 unpacked)', '没有验证:Linux 上 debug 级别对二进制大小的影响、split-debuginfo 取值的效果、[profile.*.package.NAME] 对单个依赖的覆盖、bench profile、PGO、[profile.release] panic = "abort" 对 test 的影响(cargo test 会忽略它)'], 'Cargo Profile')
